import fs from 'node:fs';import path from 'node:path';import {payloadHash,atomicJson} from '../execution/ledger.mjs';import {fundedPairPlanV2} from '../execution/funded-pair-plan-v2.mjs';import {amount,money,SCALE,TICK} from '../paper/fixed.mjs';import {pairCompletionEconomicsV1,jointPairResearchChoicesV1} from './pair-completion-economics-v1.mjs';
const rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),capture=JSON.parse(fs.readFileSync(path.join(rt,'paired-candidate-status.json')));
if(capture.name!=='baal-pair-profit-screen-20261012-v1'||capture.phase!=='complete'||capture.competitionOrders!==0)throw Error('PAIR_CAPTURE_SCOPE');
const legs=capture.roots.map(r=>{if(payloadHash(r.root)!==r.rootHash)throw Error('PAIR_CAPTURE_ROOT_HASH');return {...capture.legs.find(l=>l.marketId===r.marketId),rootObservedAt:r.receivedAt};});
const pair={ordinaryNoNoPayoutFloor:'1.000000',administrativeOrRefundRulesUnresolved:true,legs},books=capture.books.map(r=>r.book),cases=[];
for(const budget of ['1.000000','10.000000','100.000000']){
 const plan=fundedPairPlanV2({pair,books,now:capture.at,budgets:Object.fromEntries(['cashAvailable','eventRemaining','grossRemaining','maximumExceptionLoss','maximumUnhedgedPrincipal','maximumModeledUnwindLoss'].map(k=>[k,budget]))});
 const joint=jointPairResearchChoicesV1(plan.candidates??[]);
 if(!joint.length){cases.push({illustrativeCashBudget:budget,reason:plan.reason,jointBothFirstLegScenariosFunded:false});continue;}
 const chosen=joint[0];let liquidation=0n,complete=true;
 for(const book of books){let left=chosen.quantity,total=0n,allocated=0n;for(const l of book.asks){total+=BigInt(l.quantity);const cumulative=total/100n,capacity=Number(cumulative-allocated);allocated=cumulative;const q=Math.min(left,capacity),p=SCALE-amount(l.price)-TICK;if(p<TICK)break;liquidation+=p*BigInt(q);left-=q;if(!left)break;}if(left)complete=false;}
 cases.push({illustrativeCashBudget:budget,jointBothFirstLegScenariosFunded:true,...chosen,datedImmediateStressedLiquidationPnl:complete?money(liquidation-amount(chosen.principal)):null,exceptionSensitivity:['0.000000','0.005000','0.010000','0.020000'].map(exceptionProbability=>pairCompletionEconomicsV1({ordinarySurplus:chosen.ordinarySurplus,unmatchedUnwindLoss:chosen.worstUnmatchedUnwindLoss,zeroPayoutLoss:chosen.principal,exceptionProbability}))});
}
const report={at:new Date().toISOString(),captureAt:capture.at,captureHash:payloadHash(capture),marketIds:legs.map(l=>l.marketId),cases,budgetsAreIllustrativeNotActualAccountCash:true,ordinarySinglePartyPayoutPremiseRequiresIndependentVerification:true,zeroPayoutExceptionIsAnUnestimatedStressScenario:true,collateralAdvanceAssumed:'0.000000',currentExecutionReceiptsFresh:false,actualOrders:0,profitabilityEstablished:false};atomicJson('data/paired-capture-economics-20261012.json',report);console.log(JSON.stringify({cases:cases.map(c=>({cash:c.illustrativeCashBudget,quantity:c.quantity,principal:c.principal,ordinarySurplus:c.ordinarySurplus,immediatePnl:c.datedImmediateStressedLiquidationPnl})),actualOrders:0}));
